class KeyValuePair {
  KeyValuePair._(this._bc, this._bcOffset);
  factory KeyValuePair(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<KeyValuePair> reader = _KeyValuePairReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  String? get key =>
      const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  VdataTypeId? get valueType => VdataTypeId._createOrNull(
    const fb.Uint8Reader().vTableGetNullable(_bc, _bcOffset, 6),
  );
  dynamic get value {
    switch (valueType?.value) {
      case 1:
        return Uint8.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 2:
        return Int8.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 3:
        return Uint16.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 4:
        return Int16.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 5:
        return Uint32.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 6:
        return Int32.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 7:
        return Float32.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 8:
        return Bool.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 9:
        return StringValue.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 10:
        return Uint64.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 11:
        return Int64.reader.vTableGetNullable(_bc, _bcOffset, 8);
      case 12:
        return Double.reader.vTableGetNullable(_bc, _bcOffset, 8);
      default:
        return null;
    }
  }

  @override
  String toString() {
    return 'KeyValuePair{key: ${key}, valueType: ${valueType}, value: ${value}}';
  }

  KeyValuePairT unpack() =>
      KeyValuePairT(key: key, valueType: valueType, value: value);

